const items = $input.all();
return items.map(item => {
  const body = item.json.body || item.json;

  // Tách first_name và last_name nếu CRM trả về full_name
  const fullName = (body.full_name || body.name || '').trim();
  const nameParts = fullName.split(' ');
  const firstName = body.first_name || (nameParts.length > 1 ? nameParts[0] : fullName);
  const lastName = body.last_name || (nameParts.length > 1 ? nameParts.slice(1).join(' ') : '');

  return {
    json: {
      external_source: body.external_source || 'hubspot',
      external_id: String(body.crm_id || body.external_id || body.id || 'EXT-' + Date.now()),
      first_name: firstName || 'Nguyen',
      last_name: lastName || 'Van A',
      company_name: body.company_name || body.company || '',
      email: body.email || '',
      phone: body.phone || '',
      source: 'crm_sync',
      status: 'new'
    }
  };
});
